with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'أرصاد الطاقة المتجددة وتطبيقات الطقس في البنية التحتية','تقييم الطاقة الشمسية والرياح والتنبؤ بالإنتاج والطلب وتأثير الطقس في شبكات الكهرباء والنقل والبنية التحتية.',40,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد والطاقة الشمسية والرياح',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الطقس والطاقة والمرافق',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('solar-resource-assessment','تقييم مورد الطاقة الشمسية','تحليل الإشعاع الأفقي والمباشر والمنتشر.','{"blocks":[{"type":"text","text":"يعرض الدرس تقييم مورد الطاقة الشمسية ضمن تطبيقات المعلومات الجوية والمناخية في الطاقة والبنية التحتية."},{"type":"text","text":"المفهوم المحوري: تحليل الإشعاع الأفقي والمباشر والمنتشر.، مع تحديد المتغيرات الجوية التي تؤثر في الأصل أو الخدمة."},{"type":"text","text":"يحدد المستخدم والقرار التشغيلي والفترة الزمنية ومقياس البيانات المطلوب."},{"type":"text","text":"تجمع بيانات المحطات والنماذج والأقمار والقياسات المتخصصة وسجلات التشغيل."},{"type":"text","text":"تراجع جودة القياسات ومواقع الحساسات والتغطية الزمنية والمكانية قبل بناء التقديرات."},{"type":"text","text":"تحلل العلاقة بين المتغيرات الجوية والأداء مع فصل التأثيرات الموسمية عن التغيرات التشغيلية."},{"type":"text","text":"تستخدم نماذج أو مؤشرات مناسبة ويتم توثيق الافتراضات ومعاملات التحويل."},{"type":"text","text":"تقارن النتائج ببيانات الإنتاج أو الأعطال أو القياسات الميدانية لتقييم الأداء."},{"type":"text","text":"تختبر السيناريوهات والظواهر المتطرفة وتوضح نطاق عدم اليقين ومخاطر سوء التعميم."},{"type":"text","text":"تحول المخرجات إلى خرائط أو توقعات أو مؤشرات دعم قرار بالتنسيق مع الجهة القطاعية."},{"type":"text","text":"مثال تطبيقي: مقارنة توقع الإنتاج أو الطلب تحت سيناريوهات جوية مختلفة مع تحليل أثر السحب أو الحرارة أو الرياح."},{"type":"callout","text":"الخلاصة: دمج الطقس مع بيانات التشغيل يساعد على التخطيط، بشرط التحقق من العلاقة محلياً وتوثيق القيود."}]}',4360,55,'["تحديد المتغيرات الجوية المؤثرة","ربط التوقعات ببيانات القطاع","تقييم الأداء والمخاطر التشغيلية"]','الأرصاد والطاقة الشمسية والرياح'),
('solar-radiation-components','مكونات الإشعاع الشمسي وقياسها','GHI وDNI وDHI وأجهزة القياس.','{"blocks":[{"type":"text","text":"يعرض الدرس مكونات الإشعاع الشمسي وقياسها ضمن تطبيقات المعلومات الجوية والمناخية في الطاقة والبنية التحتية."},{"type":"text","text":"المفهوم المحوري: GHI وDNI وDHI وأجهزة القياس.، مع تحديد المتغيرات الجوية التي تؤثر في الأصل أو الخدمة."},{"type":"text","text":"يحدد المستخدم والقرار التشغيلي والفترة الزمنية ومقياس البيانات المطلوب."},{"type":"text","text":"تجمع بيانات المحطات والنماذج والأقمار والقياسات المتخصصة وسجلات التشغيل."},{"type":"text","text":"تراجع جودة القياسات ومواقع الحساسات والتغطية الزمنية والمكانية قبل بناء التقديرات."},{"type":"text","text":"تحلل العلاقة بين المتغيرات الجوية والأداء مع فصل التأثيرات الموسمية عن التغيرات التشغيلية."},{"type":"text","text":"تستخدم نماذج أو مؤشرات مناسبة ويتم توثيق الافتراضات ومعاملات التحويل."},{"type":"text","text":"تقارن النتائج ببيانات الإنتاج أو الأعطال أو القياسات الميدانية لتقييم الأداء."},{"type":"text","text":"تختبر السيناريوهات والظواهر المتطرفة وتوضح نطاق عدم اليقين ومخاطر سوء التعميم."},{"type":"text","text":"تحول المخرجات إلى خرائط أو توقعات أو مؤشرات دعم قرار بالتنسيق مع الجهة القطاعية."},{"type":"text","text":"مثال تطبيقي: مقارنة توقع الإنتاج أو الطلب تحت سيناريوهات جوية مختلفة مع تحليل أثر السحب أو الحرارة أو الرياح."},{"type":"callout","text":"الخلاصة: دمج الطقس مع بيانات التشغيل يساعد على التخطيط، بشرط التحقق من العلاقة محلياً وتوثيق القيود."}]}',4370,55,'["تحديد المتغيرات الجوية المؤثرة","ربط التوقعات ببيانات القطاع","تقييم الأداء والمخاطر التشغيلية"]','الأرصاد والطاقة الشمسية والرياح'),
